VAL = {'baseline': (12, 10, 18, 110), 'logistic': (21, 12, 9, 108), 'tree': (24, 17, 6, 103)}   # (TP, FP, FN, TN) on 150 validation customers
def metrics(tp, fp, fn, tn):
    p = tp / (tp + fp)
    r = tp / (tp + fn)
    return {'accuracy': (tp + tn) / (tp + fp + fn + tn), 'precision': p, 'recall': r, 'f1': 2 * p * r / (p + r)}
def meets_goal(m):
    return m['recall'] >= 0.75 and m['precision'] >= 0.5
m = metrics(*VAL['logistic'])
print('recall ok:', m['recall'] >= 0.75, ' precision ok:', m['precision'] >= 0.5, ' goal met:', meets_goal(m))
# prints: recall ok: False  precision ok: True  goal met: False

VAL = {'baseline': (12, 10, 18, 110), 'logistic': (21, 12, 9, 108), 'tree': (24, 17, 6, 103)}   # (TP, FP, FN, TN) on 150 validation customers
def metrics(tp, fp, fn, tn):
    p = tp / (tp + fp)
    r = tp / (tp + fn)
    return {'accuracy': (tp + tn) / (tp + fp + fn + tn), 'precision': p, 'recall': r, 'f1': 2 * p * r / (p + r)}
for name in ('baseline', 'logistic'):
    m = metrics(*VAL[name])
    print(name, 'accuracy', round(m['accuracy'], 2), 'recall', round(m['recall'], 2))
# prints: baseline accuracy 0.81 recall 0.4
# prints: logistic accuracy 0.86 recall 0.7
